def get_valid_moves(n, chosen_set, player_moves):
    """
    Returns a list of valid moves for the current player.
    A move x is valid if:
    1. 1 <= x <= n and x is not in chosen_set (Rule i).
    2. x is not consecutive to any number in player_moves (Rule ii).
    """
    valid_moves = []
    for x in range(1, n + 1):
        if x not in chosen_set:
            # Check Rule (ii): consecutive to numbers chosen by this player
            is_consecutive = False
            for m in player_moves:
                if abs(x - m) == 1:
                    is_consecutive = True
                    break
            if not is_consecutive:
                valid_moves.append(x)
    return valid_moves

