# Outcomes definition:
# DRAW: The game ends with all numbers chosen.
# ALICE_LOSES: Alice cannot move (and the game isn't a draw).
# BOB_LOSES: Bob cannot move (and the game isn't a draw).

# Since we are checking if a draw is POSSIBLE, we assume both players play optimally
# to achieve the best outcome for themselves (Win > Draw > Loss).

def solve_game(n, chosen_set, alice_moves, bob_moves, is_alice_turn, path):
    """
    Recursively solves the game for n.
    Returns a set of possible outcomes (e.g., {'DRAW', 'ALICE_LOSES'}) reachable from this state
    under optimal play assumptions, or None if the path is invalid/terminating immediately.

    For simplicity in simulation, we will track *all* possible outcomes achievable from this state
    by exploring all sequences, as the problem asks if a draw *is possible*.
    """

    current_player_moves = alice_moves if is_alice_turn else bob_moves

    valid_moves = get_valid_moves(n, chosen_set, current_player_moves)

    # Terminal State Check
    if not valid_moves:
        # Current player cannot move, they lose.
        if is_alice_turn:
            return {'ALICE_LOSES'}
        else:
            return {'BOB_LOSES'}

    # Check for Draw condition (all numbers chosen)
    if len(chosen_set) == n:
        return {'DRAW'}

    possible_outcomes = set()

    for move in valid_moves:
        new_chosen_set = chosen_set | {move}
        new_path = path + [move]

        if is_alice_turn:
            new_alice_moves = alice_moves | {move}
            outcome = solve_game(n, new_chosen_set, new_alice_moves, bob_moves, False, new_path)
        else:
            new_bob_moves = bob_moves | {move}
            outcome = solve_game(n, new_chosen_set, alice_moves, new_bob_moves, True, new_path)

        possible_outcomes.update(outcome)

    return possible_outcomes

